import 'package:flutter/material.dart';
import 'specialty_section_header.dart';
class TipsSection extends StatelessWidget { final String title; final Color accentColor; final List<Widget> tips; final VoidCallback? onSeeAll; const TipsSection({super.key,this.title='نصائح صحية',required this.accentColor,required this.tips,this.onSeeAll}); @override Widget build(BuildContext context){return Column(crossAxisAlignment:CrossAxisAlignment.start,children:[SpecialtySectionHeader(title:title,accentColor:accentColor,onSeeAll:onSeeAll),const SizedBox(height:10),if(tips.isEmpty)const Padding(padding:EdgeInsets.all(12),child:Text('لا توجد نصائح منشورة حالياً'))else SizedBox(height:150,child:ListView.separated(scrollDirection:Axis.horizontal,itemCount:tips.length,separatorBuilder:(_,__)=>const SizedBox(width:10),itemBuilder:(_,i)=>SizedBox(width:220,child:tips[i]))) ]);}}
